function positionTreePopover(menu,trigger){
  menu.style.visibility='hidden';
  document.body.append(menu);
  const triggerRect=trigger.getBoundingClientRect(),menuRect=menu.getBoundingClientRect();
  let left=Math.max(8,Math.min(window.innerWidth-menuRect.width-8,triggerRect.right-menuRect.width));
  let top=triggerRect.bottom+6;
  if(top+menuRect.height>window.innerHeight-8) top=triggerRect.top-menuRect.height-6;
  menu.style.left=Math.round(left)+'px';
  menu.style.top=Math.round(Math.max(8,top))+'px';
  menu.style.visibility='visible';
}
