function ptAspect(ring){if(!ring||ring.length<3)return Infinity;let best=null;for(let d=0;d<180;d++){const th=d*Math.PI/180,ux=Math.cos(th),uy=Math.sin(th),vx=-uy,vy=ux;let u0=Infinity,u1=-Infinity,v0=Infinity,v1=-Infinity;for(const p of ring){const u=p.x*ux+p.y*uy,v=p.x*vx+p.y*vy;if(u<u0)u0=u;if(u>u1)u1=u;if(v<v0)v0=v;if(v>v1)v1=v}const W=u1-u0,H=v1-v0,box=W*H;if(!best||box<best.box)best={box,W,H}}const long=Math.max(best.W,best.H),short=Math.min(best.W,best.H);return short>1e-9?long/short:Infinity}
