function ptSyncSideB(){const a=$('#partitionSideA'),b=$('#partitionSideB');const line=S.lines.find(l=>l.id===ptParentId);if(!line||a.value===''){b.innerHTML='';b.disabled=true;b.value='';return}const ring=ptFrame(line).ring,n=ring.length,ai=Number(a.value);const dir=i=>{const p=ring[i],q=ring[(i+1)%n],dx=q.x-p.x,dy=q.y-p.y,L=Math.hypot(dx,dy)||1;return{x:dx/L,y:dy/L}};const da=dir(ai);const opts=[];for(let i=0;i<n;i++){if(i===ai||(i-ai+n)%n===1||(ai-i+n)%n===1)continue;const d=dir(i);opts.push({i,par:Math.abs(da.x*d.x+da.y*d.y)})}opts.sort((x,y)=>y.par-x.par);b.innerHTML=opts.map(o=>'<option value="'+o.i+'">Side '+(o.i+1)+'</option>').join('');b.disabled=false;b.value=opts.length?String(opts[0].i):''}function ptUpdateAccept(){$('#partitionAcceptBtn').disabled=!(ptPlan&&ptPlan.ok&&(!ptPlan.failing||$('#partitionAllowExceptions').checked))}
