function ptDrawNote(){const line=ptParentId&&S.lines.find(l=>l.id===ptParentId),mode=$('#partitionDrawMode').value,axis=$('#partitionDrawAxis').value,axisName=axis==='ns'?'north–south':axis==='ew'?'east–west':'',intro=axis==='free'?'Click once to start the line, move the cursor, then click again to finish. The line can start and end anywhere; every span where it runs through the parcel becomes a cut, so one arm of a concave parcel is enough. Press Escape to cancel.':'Click once to place the '+axisName+' line, move the cursor along it, then click again to finish. Every span where that line runs through the parcel becomes a cut. Press Escape to cancel.';if(!ptDrawnCut||!line||!ptDrawnCut.sides||ptDrawnCut.sides.length<2)return intro;const frame=ptFrame(line),n=frame.ring.length,label=i=>{const a=S.points.find(p=>p.id===frame.ids[i]),b=S.points.find(p=>p.id===frame.ids[(i+1)%n]);return 'side '+(i+1)+(a&&b?' ('+a.name+' → '+b.name+')':'')};const s=ptDrawnCut.sides,drawnDir=ptDrawnCut.axis==='ns'?'North–south ':ptDrawnCut.axis==='ew'?'East–west ':'';if(s.length===2)return 'Drawn '+drawnDir+'cut crosses '+label(s[0])+' and '+label(s[1])+'. '+(mode==='equal'?'Equal parts slide between those two sides.':'Preview it, or draw again.');return 'Drawn '+drawnDir+'line crosses '+s.length+' sides ('+s.map(label).join(', ')+') and makes '+(s.length/2)+' cuts. '+(mode==='equal'?'Equal parts needs a single-span cut.':'Preview it, or draw again.')}
