function ptDrawStart(){const line=S.lines.find(l=>l.id===ptParentId);if(!line||!line.closed)return message('Select a closed parcel first');ptDrawnCut=null;ptPlan=null;ptDraw={lineId:line.id,a:null,cursor:null,axis:$('#partitionDrawAxis').value};ptUpdateDrawNote();draw();$('#partitionDialog').close();if(map)map.getContainer().style.cursor='crosshair';ptEscHandler=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();ptDrawCancel()}};document.addEventListener('keydown',ptEscHandler,true);message('Click once to start the cut line, then click again to finish (Escape cancels)')}
