function ptDrawClick(lat,lon,point){if(!ptDraw)return;const line=S.lines.find(l=>l.id===ptDraw.lineId);if(!line)return ptDrawCleanup();const raw=ptDrawLocal(line,lat,lon);if(!raw)return;if(!ptDraw.a){ptDraw.a=raw;ptDraw.cursor=null;draw();return message('Cut line started — move the cursor and click again to finish')}const p=ptDraw.axis==='ns'?{x:ptDraw.a.x,y:raw.y}:ptDraw.axis==='ew'?{x:raw.x,y:ptDraw.a.y}:raw;if(Math.hypot(p.x-ptDraw.a.x,p.y-ptDraw.a.y)<0.1)return message('Click farther along the line to finish');const frame=ptFrame(line),cross=ptDrawCross(frame.ring,ptDraw.a,p);if(cross.error){ptDraw.cursor=p;draw();return message(cross.error)}ptDrawnCut={a:{x:ptDraw.a.x,y:ptDraw.a.y},b:{x:p.x,y:p.y},sides:cross.sides,axis:ptDraw.axis,kind:cross.straight?'line':cross.spans.length===1?'chord':'multi',spans:cross.spans.length};ptDrawCleanup();$('#partitionMethod').value='draw';ptRows();ptUpdateDrawNote();if(!$('#partitionDialog').open)$('#partitionDialog').showModal();ptPreview();message('Cut line drawn — '+(cross.spans.length>1?cross.spans.length+' cuts across the parcel':'one cut across the parcel')+'. Preview and accept, or draw again')}
let ptGhostFrame=0;function ptGhostAt(lat,lon){if(!ptDraw||!ptDraw.a)return;const line=S.lines.find(l=>l.id===ptDraw.lineId);if(!line)return;let p=ptDrawLocal(line,lat,lon);if(!p)return;if(ptDraw.axis==='ns')p={x:ptDraw.a.x,y:p.y};else if(ptDraw.axis==='ew')p={x:p.x,y:ptDraw.a.y};ptDraw.cursor=p;if(ptGhostFrame)return;ptGhostFrame=requestAnimationFrame(()=>{ptGhostFrame=0;draw()})}
