function ptSyncGroundNote(){const note=$('#partitionGroundNote');if(!note)return;const ground=!!appSettings.groundMode;note.hidden=!ground;if(ground)note.textContent='Ground reduction is on: target area, minimum area and minimum frontage are ground values. h = '+groundHeightText()+' · distance factor '+groundFactor(appSettings.groundHeight).toFixed(6)+' · area factor '+(groundFactor(appSettings.groundHeight)**2).toFixed(6)+'.'}
function ptOpen(lineId){const line=S.lines.find(l=>l.id===lineId);if(!line||!line.closed||line.ids.length<3)return message('Select a closed parcel to partition');ptParentId=lineId;ptSyncGroundNote();ptDrawnCut=null;ptDrawCleanup();const frame=ptFrame(line),names=frame.ids.map(id=>S.points.find(p=>p.id===id).name),n=names.length;$('#partitionTitle').textContent='Partition '+line.name;$('#partitionFrontage').innerHTML=names.map((nm,i)=>'<option value="'+i+'">Course '+(i+1)+': '+escapeText(nm)+' → '+escapeText(names[(i+1)%n])+'</option>').join('');$('#partitionFrontage').value='0';const opts=names.map((nm,i)=>'<option value="'+i+'">'+(i+1)+'. '+escapeText(nm)+'</option>').join('');$('#partitionCutFrom').innerHTML=opts;$('#partitionCutTo').innerHTML=opts;$('#partitionCutTo').value=String(Math.floor(n/2));const sideOpts=names.map((nm,i)=>'<option value="'+i+'">Side '+(i+1)+': '+escapeText(nm)+' → '+escapeText(names[(i+1)%n])+'</option>').join('');$('#partitionSideA').innerHTML='<option value="">Choose side 1</option>'+sideOpts;$('#partitionSideA').value='';ptSyncSideB();$('#partitionOrient').value='free';$('#partitionDrawAxis').value='free';$('#partitionDrawMode').value='single';$('#partitionDrawCount').value='2';ptUpdateDrawNote();ptPlan=null;ptSetResult('Enter the values and the result appears here.');ptUpdateAccept();ptRows();$('#partitionDialog').showModal();ptThumb();draw()}
function ptRenderPlan(){const p=ptPlan,u=p.areaU,L=p.lenU;const rows=p.parts.map(part=>'<div class="partition-part '+(part.issues.length?'fail':'pass')+'"><b>'+escapeText(part.label||part.name)+'</b><span>'+ptFmtArea(part.area,u)+'</span><span>Frontage '+ptFmtLen(part.front,L)+'</span><span>Shape '+(part.aspect>50?'over 50:1 (sliver)':Number.isFinite(part.aspect)?part.aspect.toFixed(2)+':1':'n/a')+'</span><em>'+(part.issues.length?'✗ '+escapeText(part.issues.join(', ')):'✓ passes all constraints')+'</em></div>').join('');const bal='<div class="partition-balance '+(p.balanceOk?'pass':'fail')+'">Parent'+(p.ground?' ground area':'')+' '+ptFmtArea(p.total,u)+' · parts total '+ptFmtArea(p.total+p.balance,u)+' · balance '+ptFmtArea(p.balance,u)+(p.balanceOk?' — ✓ reconciles':' — ✗ does not reconcile')+'</div>';const groundNote=p.ground?'<div class="dialog-note">Ground reduction: h = '+groundHeightText()+' · distance factor '+p.gf.toFixed(6)+' · area factor '+p.areaGF.toFixed(6)+'. Target and minimum values are ground values; cut lines are solved on the grid.</div>':'';const note=p.failing?'<div class="dialog-note">Some parts fail a minimum. Tick “Allow parts that fail” to accept them anyway.</div>':'';const shapeNote=p.shape?'<div class="dialog-note">Parts are split recursively, each cut chosen so the pieces are as square as possible. Worst part: '+(p.shape.score>50?'over 50':p.shape.score.toFixed(2))+':1 (1:1 is square).</div>':'';ptSetResult(groundNote+rows+bal+shapeNote+note)}
function ptPreview(){const res=ptBuild();if(res.error){ptPlan=null;ptSetResult('✗ '+escapeText(res.error));ptUpdateAccept();ptThumb();draw();return}ptPlan=res;ptRenderPlan();ptUpdateAccept();ptThumb();draw()}
