const PT_PALETTE=['#cfe3ff','#d6f5e6','#ffe9c7','#eadcff','#d8f3f3','#ffd6e7'];
function ptThumb(){const box=$('#partitionVisual');if(!box)return;const line=ptParentId&&S.lines.find(l=>l.id===ptParentId);if(!line||!line.closed){box.innerHTML='';return}const frame=ptFrame(line),ring=frame.ring,n=ring.length;if(n<3){box.innerHTML='';return}const xs=ring.map(v=>v.x),ys=ring.map(v=>v.y);const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const VW=360,VH=200,pad=16;const sc=Math.min((VW-2*pad)/((maxX-minX)||1),(VH-2*pad)/((maxY-minY)||1));const offX=(VW-(maxX-minX)*sc)/2,offY=(VH-(maxY-minY)*sc)/2;const X=v=>(offX+(v.x-minX)*sc).toFixed(1),Y=v=>(offY+(maxY-v.y)*sc).toFixed(1);const pts=r=>r.map(v=>X(v)+','+Y(v)).join(' ');const plan=ptPlan&&ptPlan.parentId===line.id?ptPlan:null;const method=$('#partitionMethod').value;let svg='';if(plan){plan.parts.forEach((part,i)=>{if(part.ring.length<3)return;const cx=part.ring.reduce((s,v)=>s+v.x,0)/part.ring.length,cy=part.ring.reduce((s,v)=>s+v.y,0)/part.ring.length;const fill=part.issues.length?'#fecaca':PT_PALETTE[i%PT_PALETTE.length];svg+='<polygon points="'+pts(part.ring)+'" fill="'+fill+'" stroke="#1f2a3d" stroke-width="1.2" stroke-linejoin="round"/><text x="'+X({x:cx})+'" y="'+Y({y:cy})+'" text-anchor="middle" dominant-baseline="middle" font-size="12" font-weight="700" fill="#1f2a3d">'+(i+1)+'</text>'});plan.cuts.forEach(c=>{svg+='<line x1="'+X(c.a)+'" y1="'+Y(c.a)+'" x2="'+X(c.b)+'" y2="'+Y(c.b)+'" stroke="#f47752" stroke-width="2" stroke-dasharray="6 4"/>'})}else{svg+='<polygon points="'+pts(ring)+'" fill="#eef3fb" stroke="#1f2a3d" stroke-width="1.2" stroke-linejoin="round"/>'}const orientNow=$('#partitionOrient').value;const hl=method==='cut'?[]:method==='draw'&&ptDrawnCut&&ptDrawnCut.sides?ptDrawnCut.sides:method==='equal'&&orientNow==='sides'?[Number($('#partitionSideA').value),Number($('#partitionSideB').value)]:method==='equal'&&orientNow!=='free'?[]:[Number($('#partitionFrontage').value)||0];hl.forEach(fi=>{const A=ring[fi],B=ring[(fi+1)%n];svg+='<line x1="'+X(A)+'" y1="'+Y(A)+'" x2="'+X(B)+'" y2="'+Y(B)+'" stroke="#3478f6" stroke-width="4" stroke-linecap="round"/>'});box.innerHTML='<svg viewBox="0 0 '+VW+' '+VH+'" role="img" aria-label="Drawing of the parcel split">'+svg+'</svg><div class="partition-visual-key"><span><i style="background:#3478f6"></i>Frontage</span><span><i style="background:#f47752"></i>Cut</span><span><i style="background:#cfe3ff"></i>Part</span></div>'}
function ptCommit(){if(!ptPlan||!ptPlan.ok)return;const line=S.lines.find(l=>l.id===ptPlan.parentId);if(!line)return message('The parcel no longer exists; preview again');if(line.ids.join('|')!==ptPlan.frame.ids.join('|'))return message('The parcel changed; preview again');const plan=ptPlan,idOf=new Map();const pidFor=v=>{if(v.pid)return v.pid;const corner=plan.frame.ring.find(r=>Math.hypot(r.x-v.x,r.y-v.y)<1e-4);if(corner)return corner.pid;const key=v.x.toFixed(6)+','+v.y.toFixed(6);if(idOf.has(key))return idOf.get(key);const g=plan.frame.toG(v);const p={id:String(Date.now()+Math.random()),name:'Point '+String(S.points.length+1).padStart(3,'0'),lat:g.lat,lon:g.lon};S.points.push(p);idOf.set(key,p.id);return p.id};const idx=S.lines.indexOf(line);S.lines.splice(idx,1);const newIds=[];plan.parts.forEach(part=>{const ids=part.ring.map(pidFor);const ln={id:nextLineId(),name:part.label||part.name,ids,closed:true};if(plan.ground)ln.partitionGround={height:appSettings.groundHeight,heightUnit:appSettings.groundHeightUnit,distanceFactor:plan.gf,areaFactor:plan.areaGF};S.lines.splice(idx+newIds.length,0,ln);newIds.push(ln.id)});pruneMeasurements();pushHistory('partition parcel');S.selected=newIds[0];ptPlan=null;ptParentId=null;save();inspect();refreshTree();draw();$('#partitionDialog').close();message('Parcel partitioned into '+newIds.length+' parts'+(plan.ground?' · ground areas/frontages at '+groundHeightText():''))}
function drawPartitionPreview(){if(!ptPlan||!x||!w)return;const fills=['rgba(52,120,246,.22)','rgba(244,119,82,.22)','rgba(40,174,128,.22)','rgba(155,89,182,.22)'];x.save();ptPlan.parts.forEach((part,i)=>{if(part.ring.length<3)return;x.beginPath();part.ring.forEach((v,k)=>{const q=pos(ptPlan.frame.toG(v));k?x.lineTo(q.x,q.y):x.moveTo(q.x,q.y)});x.closePath();x.fillStyle=part.issues.length?'rgba(220,38,38,.22)':fills[i%fills.length];x.fill();x.setLineDash([]);x.strokeStyle='#1f2a3d';x.lineWidth=1.5;x.stroke();const cx=part.ring.reduce((s,v)=>s+v.x,0)/part.ring.length,cy=part.ring.reduce((s,v)=>s+v.y,0)/part.ring.length;const q=pos(ptPlan.frame.toG({x:cx,y:cy}));const text=(part.label||part.name)+' · '+ptFmtArea(part.area,ptPlan.areaU);x.font='600 11px Roboto,Arial,sans-serif';x.textAlign='center';x.textBaseline='middle';const width=x.measureText(text).width+14;x.fillStyle='#ffffffed';x.beginPath();x.roundRect(q.x-width/2,q.y-11,width,22,6);x.fill();x.fillStyle='#263244';x.fillText(text,q.x,q.y)});x.setLineDash([8,5]);x.strokeStyle='#f47752';x.lineWidth=2;ptPlan.cuts.forEach(c=>{const A=pos(ptPlan.frame.toG(c.a)),B=pos(ptPlan.frame.toG(c.b));x.beginPath();x.moveTo(A.x,A.y);x.lineTo(B.x,B.y);x.stroke()});x.restore()}
function ptSurvey(line){const frame=ptFrame(line),ring=frame.ring,n=ring.length;const names=frame.ids.map(id=>S.points.find(p=>p.id===id).name);const area=ptFrameArea(frame,ring),ground=!!appSettings.groundMode,gf=ground?groundFactor(appSettings.groundHeight):1;let per=0,sx=0,sy=0;const rows=[];for(let i=0;i<n;i++){const a=ring[i],b=ring[(i+1)%n],dE=b.x-a.x,dN=b.y-a.y,len=Math.hypot(dE,dN);per+=len*gf;sx+=dE;sy+=dN;rows.push('<div class="coord-pair"><span>'+(i+1)+'. '+escapeText(names[i])+' → '+escapeText(names[(i+1)%n])+'</span><b>'+ptBearing(dE,dN)+' · '+ptFmtLen(len*gf,measureUnit('length'))+'</b></div>')}return '<div class="parcel-survey">'+(ptSelfIntersects(ring)?'<div class="coord-pair"><span>Area</span><b>Not valid: boundary crosses itself or touches another side</b></div>':'')+'<div class="coord-pair" style="'+(ptSelfIntersects(ring)?'display:none':'')+'"><span>Area'+(ground?' (ground)':'')+'</span><b>'+ptFmtArea(area*gf*gf,measureUnit('area'))+'</b></div><div class="coord-pair"><span>Perimeter</span><b>'+ptFmtLen(per,measureUnit('length'))+'</b></div>'+(ground?'<div class="coord-pair"><span>Ground factor</span><b>h '+groundHeightText()+' · '+gf.toFixed(6)+'</b></div>':'')+'<div class="coord-pair"><span>Closure misclosure</span><b>'+ptFmtLen(Math.hypot(sx,sy)*gf,measureUnit('length'))+'</b></div><div class="section-title"><span>COURSES (BEARING · DISTANCE)</span></div>'+rows.join('')+'</div>'}
