let ptPriorInspect=inspect;inspect=function(...args){ptPriorInspect(...args);const line=S.lines.find(q=>q.id===S.selected);if(line&&line.closed&&line.ids.length>=3){const host=$('#inspectorContent .inspector-details');if(host){host.insertAdjacentHTML('afterbegin','<div class="inspector-top-action"><button class="primary-button" id="partitionParcelBtn" type="button">Partition parcel…</button></div>');host.insertAdjacentHTML('beforeend',ptSurvey(line));$('#partitionParcelBtn')?.addEventListener('click',()=>ptOpen(line.id))}}};
