function ptAutoFit(){if(!ptParentId)return message('Open a parcel to partition first');const method=$('#partitionMethod').value;if(method==='cut')return message('Auto fit applies to area and equal-part splits');if(method==='equal'&&$('#partitionOrient').value!=='free')return message('Auto fit applies to the free cut direction only');const square=method==='equal'&&$('#partitionOptimize').checked;const line=S.lines.find(l=>l.id===ptParentId);const ring=ptFrame(line).ring,n=ring.length;const fSel=$('#partitionFrontage'),input=$('#partitionAngle'),origF=fSel.value,origA=input.value;const len=f=>Math.hypot(ring[(f+1)%n].x-ring[f].x,ring[(f+1)%n].y-ring[f].y);const score=(f,a)=>{fSel.value=String(f);input.value=String(a);const r=ptBuild();if(r.error||!r.parts.length)return null;const fr=r.parts.map(p=>p.front),mean=fr.reduce((s,v)=>s+v,0)/fr.length,spread=mean>0?(Math.max(...fr)-Math.min(...fr))/mean:Infinity;return{f,a,failing:r.failing?1:0,worst:Math.max(...r.parts.map(p=>p.ring.length>=3?p.aspect:Infinity)),spread,len:len(f)}};const better=(x,y)=>{if(!y)return true;if(x.failing!==y.failing)return x.failing<y.failing;const w1=Math.round(x.worst*50),w2=Math.round(y.worst*50);if(w1!==w2)return w1<w2;const s1=Math.round(x.spread*100),s2=Math.round(y.spread*100);if(s1!==s2)return s1<s2;return x.len>y.len};const angles=square?[90]:Array.from({length:60},(_,i)=>i*3);let best=null;for(let f=0;f<n;f++)for(const a of angles){const s=score(f,a);if(s&&better(s,best))best=s}if(!best){fSel.value=origF;input.value=origA;return message('No valid frontage found for these settings')}if(!square)for(const step of [0.5,0.1]){const c=best.a;for(let k=-6;k<=6;k++){const a=((Math.round((c+k*step)*10)/10)%180+180)%180;const s=score(best.f,a);if(s&&better(s,best))best=s}}fSel.value=String(best.f);input.value=square?origA:String(best.a);ptPreview();message('Auto fit: course '+(best.f+1)+(square?' (square mode: cuts do not depend on the frontage)':', angle '+best.a.toFixed(1)+'°')+' · worst part '+(Number.isFinite(best.worst)?best.worst.toFixed(2):'n/a')+':1')}$('#partitionPreviewBtn').onclick=ptPreview;$('#partitionAutoFit').onclick=ptAutoFit;
