function drawInternalAngles(){if(!x||!w||map&&surveyVectorLayer&&S.layer!=='blank'&&!S.hidden.base)return;x.save();x.font='600 10px Roboto,Arial,sans-serif';x.textAlign='center';x.textBaseline='middle';for(const line of S.lines){if(!line.closed||!line.showAngles||line.ids.length<3)continue;const pts=line.ids.map(id=>S.points.find(p=>p.id===id)).filter(Boolean);if(pts.length<3)continue;const screen=pts.map(pos),{winding,angles}=internalAngleData(pts);for(let i=0;i<screen.length;i++){const a=screen[(i+screen.length-1)%screen.length],v=screen[i],b=screen[(i+1)%screen.length],angle=angles[i],radius=Math.min(23,Math.hypot(v.x-a.x,v.y-a.y)*.45,Math.hypot(b.x-v.x,b.y-v.y)*.45);if(radius<3)continue;const start=Math.atan2(b.y-v.y,b.x-v.x),end=start+(winding>0?1:-1)*angle;x.beginPath();x.arc(v.x,v.y,radius,start,end,winding<0);x.strokeStyle=line.color||'#21a67a';x.lineWidth=2;x.stroke();const mid=start+(winding>0?1:-1)*angle/2,tx=v.x+Math.cos(mid)*(radius+13),ty=v.y+Math.sin(mid)*(radius+13),label=(angle*180/Math.PI).toFixed(1)+'°',tw=x.measureText(label).width+12;x.fillStyle='#ffffffed';x.beginPath();x.roundRect(tx-tw/2,ty-9,tw,18,6);x.fill();x.strokeStyle=line.color||'#21a67a';x.lineWidth=1;x.stroke();x.fillStyle='#263244';x.fillText(label,tx,ty)}}x.restore()}
